def features(s, x):
    (u, v) = (s['panel_a'][k] for k in ('u', 'v'))
    (i, j) = np.triu_indices(len(u), 1)
    pars = []
    for k in range(u.shape[1]):
        d = u[i, k] - u[j, k]
        ok = np.abs(d) > 1e-08
        m = np.median((v[i[ok], k] - v[j[ok], k]) / d[ok])
        r = v[:, k] - m * u[:, k]
        r -= np.median(r)
        g = np.abs(r) < max(0.001, 6 * np.median(abs(r)))
        pars.append(_ls(_ones(u[g, k:k + 1]), v[g, k]))
    (off, scale) = np.array(pars).T
    z = (x - off) / scale
    (b, c) = (s['panel_b'], s['panel_c'])

    def q(w):
        return _ones(w[:, [0, 0, 1, 2]] * w[:, [1, 3, 2, 3]])

    def r(w):
        return _ones(np.cos(2.4 * w))
    L = _ones(z) @ _ls(_ones(b['u']), b['v'])
    Q = q(z) @ _ls(q(c['u']), c['v1'])
    R = r(z) @ _ls(r(c['u']), c['v2'])
    return (z, L, Q, R, q(z)[:, 1:], r(z)[:, 1:])
